WITH valid AS (SELECT *, quantity * unit_price AS line_total, ROUND(unit_price * 100, 2) AS unit_price_adjusted FROM order_items WHERE quantity < 7), scored AS (SELECT id, order_id, product_id, quantity, line_total, LAG(unit_price, 1) OVER (PARTITION BY product_id, order_id ORDER BY quantity, id) AS prev_unit_price, SUM(quantity) OVER w_hist AS cumulative_quantity, ROW_NUMBER() OVER (ORDER BY unit_price_adjusted DESC, id) AS event_seq, AVG(unit_price_adjusted) OVER (PARTITION BY product_id, order_id ORDER BY line_total, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS unit_price_adjusted_avg_6_prior, FIRST_VALUE(line_total, TRUE) OVER (PARTITION BY product_id, order_id ORDER BY unit_price_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_line_total FROM valid WHERE line_total IS NULL WINDOW w_hist AS (PARTITION BY order_id, product_id ORDER BY unit_price_adjusted, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT *, AVG(unit_price_adjusted_avg_6_prior) OVER (PARTITION BY order_id, product_id ORDER BY cumulative_quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_unit_price_adjusted_avg_6_prior, COUNT(unit_price_adjusted_avg_6_prior) OVER (PARTITION BY order_id, product_id ORDER BY cumulative_quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_unit_price_adjusted_avg_6_prior, MIN(unit_price_adjusted_avg_6_prior) OVER (PARTITION BY order_id, product_id ORDER BY cumulative_quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_unit_price_adjusted_avg_6_prior FROM scored), kept_keys AS (SELECT id FROM metrics EXCEPT DISTINCT SELECT id FROM order_items WHERE unit_price BETWEEN 160 AND 390), kept_rows AS (SELECT s.* FROM metrics s JOIN kept_keys k ON s.id = k.id), base AS (SELECT *, ROUND(last3_min_unit_price_adjusted_avg_6_prior, 0) AS last3_min_unit_price_adjusted_avg_6_prior_rounded FROM kept_rows WHERE last3_count_unit_price_adjusted_avg_6_prior > 10), joined AS (SELECT src.order_id, src.product_id, src.line_total, src.prev_unit_price, src.event_seq, src.unit_price_adjusted_avg_6_prior, src.first_known_line_total, src.last3_avg_unit_price_adjusted_avg_6_prior, src.last3_count_unit_price_adjusted_avg_6_prior, src.last3_min_unit_price_adjusted_avg_6_prior, src.last3_min_unit_price_adjusted_avg_6_prior_rounded, p.launch_date, p.category, p.cost FROM base src JOIN products p ON src.product_id <=> p.id), joined_order_items AS (SELECT a.order_id, a.product_id, a.line_total, a.prev_unit_price, a.unit_price_adjusted_avg_6_prior, a.last3_avg_unit_price_adjusted_avg_6_prior, a.last3_min_unit_price_adjusted_avg_6_prior, a.last3_min_unit_price_adjusted_avg_6_prior_rounded, a.category, a.cost, d.price FROM joined a LEFT JOIN products d ON a.product_id = d.id) SELECT product_id, SORT_ARRAY(COLLECT_SET(category)) AS category_list, APPROX_PERCENTILE(prev_unit_price, 0.9) AS prev_unit_price_p90, COUNT(DISTINCT product_id) AS distinct_product_ids, COUNT(DISTINCT product_id) AS distinct_product_ids_2, SUM(last3_min_unit_price_adjusted_avg_6_prior) FILTER (WHERE category = 'Sports') AS sports_total_last3_min_unit_price_adjusted_avg_6_prior, SORT_ARRAY(COLLECT_SET(category)) AS category_list_2 FROM joined_order_items GROUP BY product_id HAVING APPROX_PERCENTILE(prev_unit_price, 0.9) > 0 ORDER BY sports_total_last3_min_unit_price_adjusted_avg_6_prior DESC NULLS LAST
